            aOrbiterK = (aOrbiterK + aOrbiterH) + 0x3E93B03A5774D863ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterK) ^ 0xCD7961089C3E674AULL) ^ aOUSaltA[(((511U - aIndex) + 250U)) & S_SALT1];
