            aIngress = aIngress + (aOrbiterA ^ RotL64(aOrbiterG, 13U));
            aIngress = aIngress + (RotL64(aOrbiterH, 21U) ^ aOrbiterJ);
            aIngress = aIngress + RotL64(aOrbiterC, 30U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererJ = aWandererJ + ((RotL64(aScatter, 23U) + RotL64(aOrbiterK, 23U)) + aOrbiterJ);
            aWandererH = aWandererH ^ ((RotL64(aPrevious, 57U) + aOrbiterJ) + RotL64(aOrbiterD, 19U));
            aWandererI = aWandererI + (((RotL64(aIngress, 18U) + aOrbiterC) + RotL64(aOrbiterJ, 47U)) + aWUSaltB[(((511U - aIndex) + 105U)) & S_SALT1]);
            aWandererG = aWandererG ^ ((RotL64(aCross, 11U) + aOrbiterA) + RotL64(aOrbiterG, 3U));
            aWandererA = aWandererA + (((RotL64(aScatter, 5U) + RotL64(aOrbiterH, 34U)) + aOrbiterF) + RotL64(aCarry, 21U));
            aWandererC = aWandererC ^ (((RotL64(aPrevious, 51U) + RotL64(aOrbiterI, 43U)) + aOrbiterA) + aWUSaltG[(((511U - aIndex) + 185U)) & S_SALT1]);
            aWandererK = aWandererK + (((RotL64(aIngress, 44U) + aOrbiterH) + RotL64(aOrbiterG, 57U)) + RotL64(aCarry, 11U));
