            aWandererI = aWandererI + ((((RotL64(aCross, 47U) + aOrbiterB) + RotL64(aOrbiterD, 41U)) + RotL64(aCarry, 35U)) + aWUSaltH[(((511U - aIndex) + 487U)) & S_SALT1]);
            aWandererC = aWandererC ^ ((RotL64(aPrevious, 53U) + RotL64(aOrbiterG, 37U)) + aOrbiterB);
