            //
            aOrbiterD = ((aOrbiterD + aOrbiterH) + 0x7B81F623F9E1864DULL) + aOUSaltB[(((511U - aIndex) + 441U)) & S_SALT1];
            aOrbiterK = ((aOrbiterK ^ aOrbiterD) ^ 0x3585D92D714F3D5CULL) ^ aOUSaltC[(((511U - aIndex) + 91U)) & S_SALT1];
