            aWandererJ = aWandererJ + ((RotL64(aPrevious, 5U) + RotL64(aOrbiterA, 3U)) + aOrbiterH);
            aWandererE = aWandererE ^ (((RotL64(aScatter, 39U) + RotL64(aOrbiterD, 43U)) + aOrbiterB) + aWUSaltG[(((511U - aIndex) + 86U)) & S_SALT1]);
            //
