            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterA = (aWandererD + RotL64(aScatter, 21U)) + 0xF30F3A7F1E0A8B78ULL;
            aOrbiterD = ((aWandererC + RotL64(aPrevious, 56U)) + RotL64(aCarry, 57U)) + 0xE1CE44DBEAC426D5ULL;
            aOrbiterF = ((aWandererB + RotL64(aCross, 47U)) + 0xDE708AA2F5746DCEULL) + aOASaltA[(((511U - aIndex) + 293U)) & S_SALT1];
