            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterE = (aWandererK + RotL64(aIngress, 39U)) + 0xF9BFA1928D7ED8D8ULL;
            aOrbiterD = (((aWandererJ + RotL64(aScatter, 29U)) + RotL64(aCarry, 13U)) + 0x0F8EA364D6130C27ULL) + aOASaltD[(((511U - aIndex) + 235U)) & S_SALT1];
            aOrbiterB = (aWandererF + RotL64(aPrevious, 11U)) + 0xA72CB7BDCC226ED5ULL;
            aOrbiterJ = (((aWandererE + RotL64(aCross, 46U)) + RotL64(aCarry, 27U)) + 0x3020D486899BCE17ULL) + aOASaltG[((aIndex + 66U)) & S_SALT1];
