            aOrbiterH = (aWandererI + RotL64(aPrevious, 44U)) + 0x77846C5862EA45CCULL;
            aOrbiterJ = ((aWandererA + RotL64(aScatter, 5U)) + RotL64(aCarry, 21U)) + 0x187A9D40D7F5C543ULL;
