            aOrbiterH = (((aWandererD + RotL64(aCross, 11U)) + RotL64(aCarry, 47U)) + 0xFD9AAD838B5AF428ULL) + aOASaltD[(((511U - aIndex) + 197U)) & S_SALT1];
            aOrbiterE = ((aWandererC + RotL64(aIngress, 29U)) + 0x53435CFAFA3C9C06ULL) + aOASaltB[((aIndex + 96U)) & S_SALT1];
