            aOrbiterF = ((aWandererE + RotL64(aIngress, 57U)) + 0x6D0C4467432F6EE5ULL) + aOASaltF[((aIndex + 422U)) & S_SALT1];
            aOrbiterG = (aWandererA + RotL64(aCross, 35U)) + 0xEE87731D3CD7CC20ULL;
