            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0xA91DEE8CA2D4CA20ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterJ) ^ 0x02E522D5DAE02BBBULL;
